import { mkdirSync, writeFileSync } from "node:fs";

const COUNT = 300;
const PAYLOAD = "x".repeat(40000);

mkdirSync("src/generated", { recursive: true });
for (let index = 0; index < COUNT; index += 1) {
  writeFileSync(
    `src/generated/module-${index}.js`,
    `export const payload${index} = ${JSON.stringify(PAYLOAD)};\nexport const value${index} = ${index};\n`,
  );
}
writeFileSync(
  "src/generated/index.js",
  Array.from({ length: COUNT }, (_unused, index) => `export { value${index} } from "./module-${index}.js";`).join("\n") + "\n",
);
console.log(`generated ${COUNT} modules`);

